std::string quote( const std::string & value )
{
    std::string out;
    out.reserve( value.size() + 2 );
    out += '\'';

    for( char c : value ) {
        if( c == '\'' || c == '\\' ) {
            out += '\\';
        }
        out += c;
    }

    out += '\'';
    return out;
}
