// AI generated by GitHub Copilot (DeepSeek V4 Pro), v3.0
bool DbImportSink::insertRows( const std::vector<DataRecord> & batch )
{
    std::string sql = "INSERT INTO " + m_table
        + " (measured_at, temp_inside, hum_inside, temp_outside, hum_outside) VALUES ";

    for( std::size_t i = 0; i < batch.size(); ++i ) {
        const DataRecord & rec = batch[ i ];

        if( i ) {
            sql += ",";
        }

        sql += "("
            + quote( rec.getRawDateTimeStr() ) + ","
            + num( rec.degrees_inside )  + ","
            + num( rec.humidity_inside ) + ","
            + num( rec.degrees_outside ) + ","
            + num( rec.humidity_outside )
            + ")";
    }

    // measured_at is UNIQUE: an existing row is updated with the values from the
    // file instead of failing (needed for --full, and safe against a race with
    // the duplicate check of the ImportRunner).
    sql += " ON DUPLICATE KEY UPDATE"
           " temp_inside=VALUES(temp_inside),"
           " hum_inside=VALUES(hum_inside),"
           " temp_outside=VALUES(temp_outside),"
           " hum_outside=VALUES(hum_outside)";

    return exec( sql );
}
