// AI generated by GitHub Copilot (DeepSeek V4 Pro), v3.0
bool DbImportSink::existingTimestamps( const std::string & day,
                                       std::set<std::string> & timestamps )
{
    timestamps.clear();

    // day = "YYYY-MM-DD"; the index on measured_at is used for the range
    const std::string sql = "SELECT measured_at FROM " + m_table
        + " WHERE measured_at >= " + quote( day + " 00:00:00" )
        + " AND measured_at < " + quote( day + " 00:00:00" ) + " + INTERVAL 1 DAY";

    auto erg = m_db.select( sql, false );

    if( !erg ) {
        const std::string err = m_db.get_error();

        // first run: the table does not exist yet
        if( err.find( "doesn't exist" ) != std::string::npos
            || err.find( "does not exist" ) != std::string::npos ) {
            return true;
        }

        m_error = err + " (sql: " + sql + ")";
        return false;
    }

    for( const auto & row : erg.row_list.values ) {
        if( !row.empty() ) {
            timestamps.insert( row[0] );
        }
    }

    return true;
}
