// AI generated by GitHub Copilot (DeepSeek V4 Pro), v2.0
bool DbImportSink::store( const std::vector<DataRecord> & batch )
{
    if( batch.empty() ) {
        return true;
    }

    if( !exec( "BEGIN" ) ) {
        return false;
    }

    if( !insertRows( batch ) ) {
        m_db.rollback();
        return false;
    }

    return exec( "COMMIT" );
}
// End of AI generated by GitHub Copilot (DeepSeek V4 Pro), v2.0

// AI generated by GitHub Copilot (DeepSeek V4 Pro), v2.0
bool DbImportSink::newestTimestamp( std::string & timestamp )
{
    timestamp.clear();

    auto erg = m_db.select( "SELECT MAX(measured_at) FROM " + m_table, false );

    if( !erg ) {
        const std::string err = m_db.get_error();

        // first run: the table does not exist yet
        if( err.find( "doesn't exist" ) != std::string::npos
            || err.find( "does not exist" ) != std::string::npos ) {
            return true;
        }

        m_error = err;
        return false;
    }

    if( erg.row_list.values.empty() || erg.row_list.values[0].empty() ) {
        return true;
    }

    // MAX() over an empty table is NULL, which MySqlDB converts to ""
    timestamp = erg.row_list.values[0][0];
    return true;
}
